// Validate webhook payload and extract call data
const payload = $input.first().json;

// Required field validation
if (!payload.call_id) {
  throw new Error('Missing required field: call_id');
}
if (!payload.event_type) {
  throw new Error('Missing required field: event_type');
}

// Only process call_end events for full processing
if (payload.event_type !== 'call_end') {
  return [{
    json: {
      status: 'acknowledged',
      call_id: payload.call_id,
      event_type: payload.event_type,
      message: 'Event acknowledged, no processing needed'
    }
  }];
}

// Extract transcript
const transcript = payload.transcript?.full_text || payload.transcript?.partial_text || '';

return [{
  json: {
    call_id: payload.call_id,
    event_type: payload.event_type,
    caller_phone: payload.caller_phone || '',
    call_duration_seconds: payload.call_duration_seconds || 0,
    transcript: transcript,
    voice_platform: payload.voice_platform?.provider || 'unknown',
    recording_url: payload.metadata?.recording_url || null,
    timestamp: payload.timestamp || new Date().toISOString(),
    process_full: true
  }
}];

