You are the AI intake processor for Ace Noir Cleaning Services. Analyze the following call transcript and extract structured lead data.

IMPORTANT RULES:
1. Check if recording consent was given (look for phrases like "is that okay" response)
2. Detect intent: walkthrough_request, quote_request, info_request, existing_customer, spam
3. Extract all available lead information
4. NEVER include pricing - mark price_discussed: false
5. For locations outside LA County, set in_service_area: false

Output ONLY valid JSON matching this structure (no markdown, no explanation):
{
  "consent_status": "granted" | "denied" | "not_asked",
  "intent": "walkthrough_request" | "quote_request" | "info_request" | "existing_customer" | "spam" | "unknown",
  "lead_status": "new_lead" | "booked" | "info_only" | "existing_customer" | "spam" | "follow_up_needed",
  "contact": {
    "caller_name": "string or null",
    "phone_confirmed": "boolean",
    "email": "string or null"
  },
  "business": {
    "business_name": "string or null",
    "facility_type": "office" | "medical" | "dental" | "school" | "warehouse" | "retail" | "restaurant" | "other" | null
  },
  "location": {
    "street_address": "string or null",
    "city": "string or null",
    "state": "CA",
    "zip": "string or null",
    "in_service_area": "boolean"
  },
  "facility_details": {
    "approx_sqft": "number or null",
    "num_restrooms": "number or null",
    "has_breakroom": "boolean or null"
  },
  "service_requirements": {
    "frequency": "string or null",
    "preferred_time": "string or null",
    "timeline": "string or null",
    "timeline_urgency": "asap" | "within_2_weeks" | "within_month" | "flexible" | null
  },
  "special_requirements": {
    "security_requirements": "string or null",
    "compliance_requirements": "array of strings",
    "other_notes": "string or null"
  },
  "pain_points": {
    "current_provider": "string or null",
    "reason_for_switch": "string or null",
    "specific_issues": "array of strings"
  },
  "walkthrough": {
    "requested": "boolean",
    "booked": "boolean",
    "proposed_datetime": "ISO 8601 string or null",
    "decision_maker_attending": "boolean or null"
  },
  "call_summary": "1-3 sentence summary of the call"
}

=Call ID: {{ $json.call_id }}
Caller Phone: {{ $json.caller_phone }}
Call Duration: {{ $json.call_duration_seconds }} seconds

TRANSCRIPT:
{{ $json.transcript }}

parameters.jsCode:
// Parse AI response and merge with call metadata
const callData = $('Validate Payload').first().json;
const aiResponse = $input.first().json;

// Parse the AI output (handle potential JSON in message content)
let extracted;
try {
  const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);
  // Try to extract JSON from the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  extracted = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(content);
} catch (e) {
  throw new Error(`Failed to parse AI response: ${e.message}`);
}

// Generate lead_id
const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const seq = Math.floor(Math.random() * 900) + 100; // Random 3-digit for demo
const lead_id = `lead_${today}_${seq}`;

// Determine next action based on lead status
let next_action = {
  action: 'no_action',
  deadline: null,
  notes: null
};

switch (extracted.lead_status) {
  case 'booked':
    next_action = {
      action: 'confirm_walkthrough',
      deadline: 'day before appointment',
      notes: 'Prepare checklist based on facility type'
    };
    break;
  case 'new_lead':
  case 'follow_up_needed':
    next_action = {
      action: 'callback_to_schedule',
      deadline: 'within 4 hours',
      notes: extracted.lead_status === 'follow_up_needed' ? 'May need manual review' : 'Schedule walkthrough'
    };
    break;
  case 'existing_customer':
    next_action = {
      action: 'route_to_account_manager',
      deadline: 'within 1 hour',
      notes: 'Check for service issues'
    };
    break;
  case 'info_only':
    next_action = {
      action: extracted.contact?.email ? 'send_info_email' : 'no_action',
      deadline: extracted.contact?.email ? 'within 24 hours' : null,
      notes: null
    };
    break;
}

// Merge all data
return [{
  json: {
    // IDs
    lead_id: lead_id,
    call_id: callData.call_id,

    // Status
    lead_status: extracted.lead_status,
    consent_status: extracted.consent_status,
    intent: extracted.intent,

    // Contact
    caller_name: extracted.contact?.caller_name || null,
    phone: callData.caller_phone,
    phone_confirmed: extracted.contact?.phone_confirmed || false,
    email: extracted.contact?.email || null,

    // Business
    business_name: extracted.business?.business_name || 'Unknown Business',
    facility_type: extracted.business?.facility_type || 'other',

    // Location
    street_address: extracted.location?.street_address || null,
    city: extracted.location?.city || null,
    state: extracted.location?.state || 'CA',
    zip: extracted.location?.zip || null,
    in_service_area: extracted.location?.in_service_area !== false,

    // Facility details
    approx_sqft: extracted.facility_details?.approx_sqft || null,
    num_restrooms: extracted.facility_details?.num_restrooms || null,
    has_breakroom: extracted.facility_details?.has_breakroom || null,

    // Service requirements
    frequency: extracted.service_requirements?.frequency || null,
    preferred_time: extracted.service_requirements?.preferred_time || null,
    timeline: extracted.service_requirements?.timeline || null,
    timeline_urgency: extracted.service_requirements?.timeline_urgency || null,

    // Special requirements
    security_requirements: extracted.special_requirements?.security_requirements || null,
    compliance_requirements: extracted.special_requirements?.compliance_requirements || [],
    special_notes: extracted.special_requirements?.other_notes || null,

    // Pain points
    current_provider: extracted.pain_points?.current_provider || null,
    reason_for_switch: extracted.pain_points?.reason_for_switch || null,
    specific_issues: extracted.pain_points?.specific_issues || [],

    // Walkthrough
    walkthrough_requested: extracted.walkthrough?.requested || false,
    walkthrough_booked: extracted.walkthrough?.booked || false,
    walkthrough_datetime: extracted.walkthrough?.proposed_datetime || null,
    decision_maker_attending: extracted.walkthrough?.decision_maker_attending || null,

    // Summary
    call_summary: extracted.call_summary || 'No summary available',

    // Call metadata
    call_duration_seconds: callData.call_duration_seconds,
    voice_platform: callData.voice_platform,
    recording_url: callData.recording_url,
    transcript_stored: extracted.consent_status !== 'denied',

    // Next action
    next_action: next_action.action,
    next_action_deadline: next_action.deadline,
    next_action_notes: next_action.notes,

    // Timestamps
    created_at: new Date().toISOString()
  }
}];

