const storeResult = $('Store Lead - Postgres').first()?.json;

const actions = ['lead_stored'];
if (calendarEvent?.id) actions.push('calendar_event_created');
actions.push('email_notification_sent');

return [{
  json: {
    status: 'success',
    call_id: leadData.call_id,
    lead_id: leadData.lead_id,
    lead_status: leadData.lead_status,
    actions_taken: actions,
    walkthrough: {
      booked: leadData.walkthrough_booked,
      datetime: leadData.walkthrough_datetime,
      calendar_event_id: calendarEvent?.id || null
    },
    notification_sent: true,
    next_action: {
      action: leadData.next_action,
      deadline: leadData.next_action_deadline
    },
    timestamp: new Date().toISOString()
  }
}];

// Log spam and return minimal response
const leadData = $input.first().json;

return [{
  json: {
    status: 'success',
    call_id: leadData.call_id,
    lead_id: null,
    lead_status: 'spam',
    actions_taken: ['call_logged'],
    message: 'Spam call detected - no lead created',
    timestamp: new Date().toISOString()
  }
}];

// Skip calendar, continue to notification
const leadData = $input.first().json;
return [{ json: leadData }];

// Merge calendar event data with lead data
const leadData = $('Merge & Format Data').first().json;
const calendarEvent = $input.first().json;

return [{
  json: {
    ...leadData,
    calendar_event_id: calendarEvent.id,
    calendar_event_link: calendarEvent.htmlLink
  }
}];
